UInt16 adc_convert (Adc_Channel adc_channel)
{
  UInt16 adc_val ;

  os_res_request (adc_res , 0) ;
    {
      adc_val = adc_convert_raw (adc_channel) ;
    }
  os_res_release (adc_res) ;

  return adc_val ;
}

